package offline;

import java.io.ByteArrayOutputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * Offline receive audit of cleartext QUIC envelopes.
 *
 * <p>The audit reads client datagrams, frames the envelopes, reconstructs packet numbers, applies
 * the routing, authentication and key epoch rules of the profile, evaluates the contained frames
 * as one transaction per packet and reports the committed state together with the canonical
 * (normalised) envelopes.</p>
 */
public final class ReceiveAudit {

    static final long MAX62 = (1L << 62) - 1;
    static final long MAX60 = 1L << 60;

    static final String BAD_HEADER = "BAD_HEADER";
    static final String CLOSED = "CLOSED";
    static final String DROP_CID = "DROP_CID";
    static final String NO_KEY = "NO_KEY";
    static final String PN_RANGE = "PN_RANGE";
    static final String AUTH = "AUTH";
    static final String DUPLICATE = "DUPLICATE";
    static final String OK = "OK";
    static final String PEER_CLOSE = "PEER_CLOSE";
    static final String KEY_UPDATE_ERROR = "KEY_UPDATE_ERROR";
    static final String FRAME_ENCODING_ERROR = "FRAME_ENCODING_ERROR";
    static final String PROTOCOL_VIOLATION = "PROTOCOL_VIOLATION";
    static final String STREAM_STATE_ERROR = "STREAM_STATE_ERROR";
    static final String STREAM_LIMIT_ERROR = "STREAM_LIMIT_ERROR";
    static final String FINAL_SIZE_ERROR = "FINAL_SIZE_ERROR";
    static final String FLOW_CONTROL_ERROR = "FLOW_CONTROL_ERROR";
    static final String CONNECTION_ID_LIMIT_ERROR = "CONNECTION_ID_LIMIT_ERROR";

    // ------------------------------------------------------------------ configuration

    private long limitConnection;
    private long limitStream;
    private long limitBidi;
    private long limitUni;
    private int limitCids;
    private long localBidi;
    private long localUni;
    private byte[][] localCids;
    private boolean[] localRetired;
    private int cidWidth;

    // ------------------------------------------------------------------ connection state

    private final boolean[] keyActive = new boolean[3];
    private final long[] largest = {-1L, -1L, -1L};
    private final Set<Long>[] seen = newSetArray();
    private long currentEpoch;
    private final TreeMap<Long, long[]> epochs = new TreeMap<>();
    private final IntervalSet[] ackRanges = {new IntervalSet(), new IntervalSet(), new IntervalSet()};
    private final long[][] ecn = {new long[3], new long[3], new long[3]};
    private final TreeMap<Long, StreamState> streams = new TreeMap<>();
    private final ByteStore[] crypto = {new ByteStore(), new ByteStore(), new ByteStore()};
    private final TreeMap<Long, PeerCid> peerCids = new TreeMap<>();
    private final Map<String, Long> cidOwner = new HashMap<>();
    private long retirePriorTo;
    private long sendMaxData;
    private long sendMaxStreamsBidi;
    private long sendMaxStreamsUni;
    private long openedBidi;
    private long openedUni;
    private long used;
    private boolean closed;
    private long[] closedInfo;

    private final List<Object> packetRows = new ArrayList<>();
    private final List<Object> datagramRows = new ArrayList<>();

    // ------------------------------------------------------------------ helper types

    private static final class StreamState {
        long high;
        Long finalSize;
        Long reset;
        Long stop;
        long sendMax;
        final ByteStore data = new ByteStore();
    }

    private static final class PeerCid {
        final byte[] cid;
        final byte[] token;

        PeerCid(byte[] cid, byte[] token) {
            this.cid = cid;
            this.token = token;
        }
    }

    /** Per packet transaction state. */
    private static final class Txn {
        final Journal journal = new Journal();
        final Map<Integer, IntervalSet> ackSnapshots = new HashMap<>();
        final Map<Integer, long[]> ecnSnapshots = new HashMap<>();
        boolean cidSnapshot;
        boolean peerSnapshot;
    }

    /** Cursor over the payload of one packet. */
    private static final class Cursor {
        final byte[] data;
        int pos;

        Cursor(byte[] data) {
            this.data = data;
        }

        long varint(int frameStart) throws FrameError {
            long[] out = new long[1];
            int consumed = QuicVarint.decode(data, pos, data.length, out);
            if (consumed < 0) {
                throw new FrameError(FRAME_ENCODING_ERROR, frameStart);
            }
            pos += consumed;
            return out[0];
        }

        byte[] bytes(int count, int frameStart) throws FrameError {
            if (count < 0 || pos + count > data.length) {
                throw new FrameError(FRAME_ENCODING_ERROR, frameStart);
            }
            byte[] result = Arrays.copyOfRange(data, pos, pos + count);
            pos += count;
            return result;
        }
    }

    /** A framed envelope of the input datagram. */
    private static final class Envelope {
        int level;
        byte[] dcid;
        byte[] scid;
        byte[] token;
        int pnLength;
        long rawPn;
        int keyPhase;
        byte[] payload;
        int nextOffset;
    }

    @SuppressWarnings("unchecked")
    private static Set<Long>[] newSetArray() {
        Set<Long>[] result = new Set[3];
        for (int i = 0; i < 3; i++) {
            result[i] = new HashSet<>();
        }
        return result;
    }

    // ------------------------------------------------------------------ entry point

    /** Audits one trace and returns its result object. */
    public Map<String, Object> audit(Main.Trace trace) {
        init(trace);
        List<Main.Event> events = trace.events;
        for (int index = 0; index < events.size(); index++) {
            Main.Event event = events.get(index);
            if (event.keys != null) {
                applyKeys(event.keys);
            } else {
                processDatagram(index, event);
            }
        }
        return buildResult();
    }

    private void init(Main.Trace trace) {
        limitConnection = trace.connection;
        limitStream = trace.stream;
        limitBidi = trace.bidi;
        limitUni = trace.uni;
        limitCids = trace.cidLimit;
        localBidi = trace.localBidi;
        localUni = trace.localUni;
        localCids = trace.localCids.toArray(new byte[0][]);
        localRetired = new boolean[localCids.length];
        cidWidth = localCids.length == 0 ? 0 : localCids[0].length;
        keyActive[0] = true;
        for (int level = 0; level < 3; level++) {
            long seed = trace.received[level];
            if (seed >= 0) {
                largest[level] = seed;
                seen[level].add(seed);
                if (level == 2) {
                    epochs.put(0L, new long[] {seed, seed, 1L});
                }
            }
        }
    }

    private void applyKeys(List<String> keys) {
        if (closed) {
            return;
        }
        for (int level = 0; level < 3; level++) {
            keyActive[level] = false;
        }
        for (String key : keys) {
            switch (key) {
                case "I":
                    keyActive[0] = true;
                    break;
                case "H":
                    keyActive[1] = true;
                    break;
                default:
                    keyActive[2] = true;
                    break;
            }
        }
    }

    // ------------------------------------------------------------------ datagram processing

    private void processDatagram(int eventIndex, Main.Event event) {
        byte[] wire = event.wire == null ? new byte[0] : event.wire;
        List<Long> auth = event.auth == null ? new ArrayList<>() : event.auth;
        ByteArrayOutputStream canonical = new ByteArrayOutputStream();
        int reached = 0;
        int accepted = 0;
        int offset = 0;
        while (offset < wire.length) {
            Envelope envelope = parseEnvelope(wire, offset);
            int attempt = reached;
            if (envelope == null) {
                addPacketRow(eventIndex, attempt, offset, null, null, null, BAD_HEADER, null);
                reached++;
                break;
            }
            reached++;
            byte[] bytes = handleEnvelope(eventIndex, attempt, offset, envelope, auth);
            if (bytes != null) {
                canonical.write(bytes, 0, bytes.length);
                accepted++;
            }
            offset = envelope.nextOffset;
        }
        datagramRows.add(Main.object(
                "event", eventIndex,
                "packets", reached,
                "accepted", accepted,
                "bytes", canonical.size(),
                "sha256", sha256(canonical.toByteArray())));
    }

    /**
     * Frames the envelope that starts at {@code offset}.
     *
     * @return the envelope or null when the header is malformed
     */
    private Envelope parseEnvelope(byte[] wire, int offset) {
        int pos = offset;
        if (pos >= wire.length) {
            return null;
        }
        int first = wire[pos++] & 0xFF;
        Envelope envelope = new Envelope();
        if ((first & 0x80) != 0) {
            boolean initial = (first & 0xFC) == 0xC0;
            boolean handshake = (first & 0xFC) == 0xE0;
            if (!initial && !handshake) {
                return null;
            }
            envelope.level = initial ? 0 : 1;
            if (pos + 4 > wire.length) {
                return null;
            }
            if (wire[pos] != 0 || wire[pos + 1] != 0 || wire[pos + 2] != 0 || wire[pos + 3] != 1) {
                return null;
            }
            pos += 4;
            if (pos >= wire.length) {
                return null;
            }
            int dcidLength = wire[pos++] & 0xFF;
            if (dcidLength > 20 || pos + dcidLength > wire.length) {
                return null;
            }
            envelope.dcid = Arrays.copyOfRange(wire, pos, pos + dcidLength);
            pos += dcidLength;
            if (pos >= wire.length) {
                return null;
            }
            int scidLength = wire[pos++] & 0xFF;
            if (scidLength > 20 || pos + scidLength > wire.length) {
                return null;
            }
            envelope.scid = Arrays.copyOfRange(wire, pos, pos + scidLength);
            pos += scidLength;
            if (initial) {
                long[] out = new long[1];
                int consumed = QuicVarint.decode(wire, pos, wire.length, out);
                if (consumed < 0) {
                    return null;
                }
                pos += consumed;
                if (out[0] > wire.length - pos) {
                    return null;
                }
                envelope.token = Arrays.copyOfRange(wire, pos, pos + (int) out[0]);
                pos += (int) out[0];
            }
            long[] out = new long[1];
            int consumed = QuicVarint.decode(wire, pos, wire.length, out);
            if (consumed < 0) {
                return null;
            }
            pos += consumed;
            envelope.pnLength = (first & 0x03) + 1;
            if (out[0] < envelope.pnLength || out[0] > wire.length - pos) {
                return null;
            }
            int length = (int) out[0];
            envelope.rawPn = readUnsigned(wire, pos, envelope.pnLength);
            envelope.payload = Arrays.copyOfRange(wire, pos + envelope.pnLength, pos + length);
            envelope.nextOffset = pos + length;
            return envelope;
        }
        // short header
        if ((first & 0x40) == 0 || (first & 0x18) != 0) {
            return null;
        }
        envelope.level = 2;
        envelope.keyPhase = (first & 0x04) != 0 ? 1 : 0;
        envelope.pnLength = (first & 0x03) + 1;
        if (pos + cidWidth + envelope.pnLength > wire.length) {
            return null;
        }
        envelope.dcid = Arrays.copyOfRange(wire, pos, pos + cidWidth);
        pos += cidWidth;
        envelope.rawPn = readUnsigned(wire, pos, envelope.pnLength);
        pos += envelope.pnLength;
        envelope.payload = Arrays.copyOfRange(wire, pos, wire.length);
        envelope.nextOffset = wire.length;
        return envelope;
    }

    private static long readUnsigned(byte[] data, int offset, int length) {
        long value = 0;
        for (int i = 0; i < length; i++) {
            value = (value << 8) | (data[offset + i] & 0xFF);
        }
        return value;
    }

    // ------------------------------------------------------------------ packet processing

    /**
     * Applies the receive rules to one framed envelope.
     *
     * @return the canonical envelope when the packet was accepted, null otherwise
     */
    private byte[] handleEnvelope(int eventIndex, int attempt, int offset, Envelope envelope,
            List<Long> auth) {
        int level = envelope.level;
        long expected = largest[level] < 0 ? 0 : largest[level] + 1;
        long pn = reconstruct(envelope.rawPn, envelope.pnLength, expected);
        int destination = matchLocalCid(envelope.dcid);
        if (closed) {
            addPacketRow(eventIndex, attempt, offset, levelName(level), pn, null, CLOSED, null);
            return null;
        }
        if (destination < 0) {
            addPacketRow(eventIndex, attempt, offset, levelName(level), pn, null, DROP_CID, null);
            return null;
        }
        if (!keyActive[level]) {
            addPacketRow(eventIndex, attempt, offset, levelName(level), pn, null, NO_KEY, null);
            return null;
        }
        if (pn > MAX62) {
            addPacketRow(eventIndex, attempt, offset, levelName(level), pn, null, PN_RANGE, null);
            return null;
        }
        Long epoch = null;
        if (level == 2) {
            Long annotation = attempt < auth.size() ? auth.get(attempt) : null;
            if (annotation == null || !epochAllowed(annotation)
                    || (annotation & 1L) != (long) envelope.keyPhase) {
                addPacketRow(eventIndex, attempt, offset, levelName(level), pn, null, AUTH, null);
                return null;
            }
            epoch = annotation;
        } else {
            Long annotation = auth.isEmpty() ? null : auth.get(0);
            if (annotation == null) {
                addPacketRow(eventIndex, attempt, offset, levelName(level), pn, null, AUTH, null);
                return null;
            }
        }
        if (seen[level].contains(pn)) {
            addPacketRow(eventIndex, attempt, offset, levelName(level), pn, epoch, DUPLICATE, null);
            return null;
        }
        if (level == 2 && !epochOrderValid(epoch, pn)) {
            closeConnection(eventIndex, attempt, 0, KEY_UPDATE_ERROR);
            addPacketRow(eventIndex, attempt, offset, levelName(level), pn, epoch, KEY_UPDATE_ERROR, null);
            return null;
        }
        Txn txn = new Txn();
        List<Frame> frames = new ArrayList<>();
        String status = OK;
        int failureOffset = -1;
        int closeOffset = -1;
        try {
            closeOffset = processFrames(envelope, frames, txn, destination);
        } catch (FrameError error) {
            txn.journal.rollback();
            status = error.code;
            failureOffset = error.offset;
        }
        if (!OK.equals(status)) {
            closeConnection(eventIndex, attempt, failureOffset, status);
            addPacketRow(eventIndex, attempt, offset, levelName(level), pn, epoch, status, null);
            return null;
        }
        if (closeOffset >= 0) {
            closeConnection(eventIndex, attempt, closeOffset, PEER_CLOSE);
        }
        txn.journal.commit();
        acceptPacket(level, pn, epoch);
        byte[] payload = canonicalPayload(frames);
        byte[] canonical = canonicalEnvelope(envelope, pn, expected, payload);
        addPacketRow(eventIndex, attempt, offset, levelName(level), pn, epoch,
                closeOffset >= 0 ? PEER_CLOSE : OK, sha256(canonical));
        return canonical;
    }

    private static String levelName(int level) {
        return level == 0 ? "I" : (level == 1 ? "H" : "A");
    }

    private void closeConnection(int event, int packet, int offset, String code) {
        if (!closed) {
            closed = true;
            closedInfo = new long[] {event, packet, offset};
            closedCode = code;
        }
    }

    private String closedCode;

    /** Accepts a packet: the packet number becomes seen and the epoch statistics grow. */
    private void acceptPacket(int level, long pn, Long epoch) {
        seen[level].add(pn);
        if (pn > largest[level]) {
            largest[level] = pn;
        }
        if (level == 2 && epoch != null) {
            long[] stats = epochs.get(epoch);
            if (stats == null) {
                stats = new long[] {pn, pn, 0L};
                epochs.put(epoch, stats);
            }
            if (pn < stats[0]) {
                stats[0] = pn;
            }
            if (pn > stats[1]) {
                stats[1] = pn;
            }
            stats[2]++;
            if (epoch == currentEpoch + 1) {
                currentEpoch = epoch;
            }
        }
    }

    private boolean epochAllowed(long annotation) {
        if (annotation == currentEpoch) {
            return true;
        }
        if (currentEpoch > 0 && annotation == currentEpoch - 1) {
            return true;
        }
        return annotation == currentEpoch + 1 && annotation <= MAX62;
    }

    private boolean epochOrderValid(long epoch, long pn) {
        for (Map.Entry<Long, long[]> entry : epochs.entrySet()) {
            long other = entry.getKey();
            if (other == epoch) {
                continue;
            }
            long[] stats = entry.getValue();
            if (stats[2] == 0) {
                continue;
            }
            if (epoch > other) {
                if (pn <= stats[1]) {
                    return false;
                }
            } else if (pn >= stats[0]) {
                return false;
            }
        }
        return true;
    }

    /** Index of the issued, unretired local connection id matching {@code dcid} or -1. */
    private int matchLocalCid(byte[] dcid) {
        for (int index = 0; index < localCids.length; index++) {
            if (localRetired[index]) {
                continue;
            }
            if (Arrays.equals(localCids[index], dcid)) {
                return index;
            }
        }
        return -1;
    }

    // ------------------------------------------------------------------ frame processing

    /**
     * Decodes and applies all frames of one packet.
     *
     * @return the payload offset of a connection close frame or -1
     */
    private int processFrames(Envelope envelope, List<Frame> frames, Txn txn, int destination)
            throws FrameError {
        byte[] payload = envelope.payload;
        int level = envelope.level;
        Cursor cursor = new Cursor(payload);
        if (payload.length == 0) {
            throw new FrameError(FRAME_ENCODING_ERROR, 0);
        }
        int closeOffset = -1;
        while (cursor.pos < payload.length) {
            int start = cursor.pos;
            long type = cursor.varint(start);
            if (QuicVarint.size(type) != encodedTypeLength(type, payload, start)) {
                throw new FrameError(FRAME_ENCODING_ERROR, start);
            }
            checkFrameLevel(type, level, start);
            Frame frame = decodeFrame(type, cursor, start);
            applyFrame(frame, level, txn, destination, start);
            frames.add(frame);
            if (frame.type == 0x1c || frame.type == 0x1d) {
                closeOffset = start;
                break;
            }
        }
        return closeOffset;
    }

    /** Number of bytes the frame type occupied on the wire. */
    private static int encodedTypeLength(long type, byte[] payload, int start) {
        int length = QuicVarint.size(type);
        int available = payload.length - start;
        return Math.min(length, available) == available && available < length ? available : length;
    }

    private static void checkFrameLevel(long type, int level, int offset) throws FrameError {
        switch ((int) type) {
            case 0x00:
            case 0x01:
            case 0x02:
            case 0x03:
            case 0x06:
            case 0x1c:
                return;
            case 0x07:
            case 0x1e:
                throw new FrameError(PROTOCOL_VIOLATION, offset);
            default:
                if (level != 2) {
                    throw new FrameError(PROTOCOL_VIOLATION, offset);
                }
                return;
        }
    }

    private Frame decodeFrame(long type, Cursor cursor, int start) throws FrameError {
        Frame frame = new Frame((int) type);
        switch ((int) type) {
            case 0x00:
            case 0x01:
                break;
            case 0x02:
            case 0x03: {
                frame.ackLargest = cursor.varint(start);
                frame.ackDelay = cursor.varint(start);
                long count = cursor.varint(start);
                frame.ackFirst = cursor.varint(start);
                if (frame.ackFirst > frame.ackLargest) {
                    throw new FrameError(FRAME_ENCODING_ERROR, start);
                }
                int remaining = cursor.data.length - cursor.pos;
                if (count > remaining / 2) {
                    throw new FrameError(FRAME_ENCODING_ERROR, start);
                }
                frame.ackPairs = new long[(int) count * 2];
                for (int i = 0; i < (int) count; i++) {
                    frame.ackPairs[2 * i] = cursor.varint(start);
                    frame.ackPairs[2 * i + 1] = cursor.varint(start);
                }
                if (type == 0x03) {
                    frame.ecn = new long[] {cursor.varint(start), cursor.varint(start),
                            cursor.varint(start)};
                }
                break;
            }
            case 0x04:
                frame.id = cursor.varint(start);
                frame.errorCode = cursor.varint(start);
                frame.finalSize = cursor.varint(start);
                break;
            case 0x05:
                frame.id = cursor.varint(start);
                frame.errorCode = cursor.varint(start);
                break;
            case 0x06:
                frame.offset = cursor.varint(start);
                frame.length = cursor.varint(start);
                frame.data = cursor.bytes((int) frame.length, start);
                break;
            case 0x08:
            case 0x09:
            case 0x0a:
            case 0x0b:
            case 0x0c:
            case 0x0d:
            case 0x0e:
            case 0x0f: {
                frame.fin = (type & 0x01) != 0;
                frame.hasLength = (type & 0x02) != 0;
                frame.hasOffset = (type & 0x04) != 0;
                frame.id = cursor.varint(start);
                if (frame.hasOffset) {
                    frame.offset = cursor.varint(start);
                }
                if (frame.hasLength) {
                    frame.length = cursor.varint(start);
                    frame.data = cursor.bytes((int) frame.length, start);
                } else {
                    frame.length = cursor.data.length - cursor.pos;
                    frame.data = cursor.bytes((int) frame.length, start);
                }
                break;
            }
            case 0x10:
                frame.finalSize = cursor.varint(start);
                break;
            case 0x11:
                frame.id = cursor.varint(start);
                frame.finalSize = cursor.varint(start);
                break;
            case 0x12:
            case 0x13:
            case 0x14:
            case 0x16:
            case 0x17:
                frame.finalSize = cursor.varint(start);
                break;
            case 0x15:
                frame.id = cursor.varint(start);
                frame.finalSize = cursor.varint(start);
                break;
            case 0x18:
                frame.sequence = cursor.varint(start);
                frame.retirePriorTo = cursor.varint(start);
                int cidLength = cursor.bytes(1, start)[0] & 0xFF;
                frame.cidLength = cidLength;
                frame.cid = cursor.bytes(cidLength, start);
                frame.token = cursor.bytes(16, start);
                break;
            case 0x19:
                frame.sequence = cursor.varint(start);
                break;
            case 0x1a:
            case 0x1b:
                frame.data = cursor.bytes(8, start);
                break;
            case 0x1c:
                frame.errorCode = cursor.varint(start);
                frame.triggerType = cursor.varint(start);
                frame.reason = cursor.bytes((int) cursor.varint(start), start);
                break;
            case 0x1d:
                frame.errorCode = cursor.varint(start);
                frame.reason = cursor.bytes((int) cursor.varint(start), start);
                break;
            case 0x30:
                frame.length = cursor.data.length - cursor.pos;
                frame.data = cursor.bytes((int) frame.length, start);
                break;
            case 0x31:
                frame.length = cursor.varint(start);
                frame.data = cursor.bytes((int) frame.length, start);
                break;
            default:
                throw new FrameError(FRAME_ENCODING_ERROR, start);
        }
        return frame;
    }

    // ------------------------------------------------------------------ frame semantics

    private void applyFrame(Frame frame, int level, Txn txn, int destination, int offset)
            throws FrameError {
        switch (frame.type) {
            case 0x00:
            case 0x01:
                break;
            case 0x02:
            case 0x03:
                applyAck(frame, level, txn, offset);
                break;
            case 0x04:
                applyResetStream(frame, txn, offset);
                break;
            case 0x05:
                applyStopSending(frame, txn, offset);
                break;
            case 0x06:
                applyCrypto(frame, level, txn, offset);
                break;
            case 0x08:
            case 0x09:
            case 0x0a:
            case 0x0b:
            case 0x0c:
            case 0x0d:
            case 0x0e:
            case 0x0f:
                applyStream(frame, txn, offset);
                break;
            case 0x10:
                applyMaxData(frame, txn);
                break;
            case 0x11:
                applyMaxStreamData(frame, txn, offset);
                break;
            case 0x12:
            case 0x13:
                applyMaxStreams(frame, txn, offset);
                break;
            case 0x14:
                break;
            case 0x15:
                applyStreamDataBlocked(frame, txn, offset);
                break;
            case 0x16:
            case 0x17:
                applyStreamsBlocked(frame, offset);
                break;
            case 0x18:
                applyNewConnectionId(frame, txn, offset);
                break;
            case 0x19:
                applyRetireConnectionId(frame, txn, destination, offset);
                break;
            case 0x1a:
            case 0x1b:
                break;
            case 0x1c:
            case 0x1d:
                break;
            case 0x30:
            case 0x31:
                break;
            default:
                throw new FrameError(FRAME_ENCODING_ERROR, offset);
        }
    }

    private void applyAck(Frame frame, int level, Txn txn, int offset) throws FrameError {
        long low = frame.ackLargest - frame.ackFirst;
        addAckRange(level, low, frame.ackLargest + 1, txn);
        for (int i = 0; i + 1 < frame.ackPairs.length; i += 2) {
            long gap = frame.ackPairs[i];
            long range = frame.ackPairs[i + 1];
            if (low < gap + 2) {
                throw new FrameError(FRAME_ENCODING_ERROR, offset);
            }
            long high = low - gap - 2;
            if (range > high) {
                throw new FrameError(FRAME_ENCODING_ERROR, offset);
            }
            long newLow = high - range;
            addAckRange(level, newLow, high + 1, txn);
            low = newLow;
        }
        if (frame.ecn != null) {
            long[] snapshot = txn.ecnSnapshots.get(level);
            if (snapshot == null) {
                snapshot = ecn[level].clone();
                txn.ecnSnapshots.put(level, snapshot);
                final long[] saved = snapshot;
                txn.journal.add(() -> System.arraycopy(saved, 0, ecn[level], 0, saved.length));
            }
            for (int i = 0; i < 3; i++) {
                if (frame.ecn[i] > ecn[level][i]) {
                    ecn[level][i] = frame.ecn[i];
                }
            }
        }
    }

    private void addAckRange(int level, long start, long end, Txn txn) {
        IntervalSet snapshot = txn.ackSnapshots.get(level);
        if (snapshot == null) {
            snapshot = ackRanges[level].copy();
            txn.ackSnapshots.put(level, snapshot);
            txn.journal.add(() -> ackRanges[level].restore(snapshot));
        }
        ackRanges[level].add(start, end);
    }

    private void applyResetStream(Frame frame, Txn txn, int offset) throws FrameError {
        checkStreamReference(frame.id, true, offset);
        StreamState stream = streamForWrite(frame.id, txn);
        if (frame.finalSize < stream.high) {
            throw new FrameError(FINAL_SIZE_ERROR, offset);
        }
        if (stream.finalSize != null && stream.finalSize.longValue() != frame.finalSize) {
            throw new FrameError(FINAL_SIZE_ERROR, offset);
        }
        if (stream.finalSize == null) {
            setFinalSize(stream, frame.finalSize, txn);
        }
        applyFlowControl(stream, frame.finalSize, txn, offset);
        if (stream.reset == null) {
            setReset(stream, frame.errorCode, txn);
        }
    }

    private void applyStopSending(Frame frame, Txn txn, int offset) throws FrameError {
        checkStreamReference(frame.id, false, offset);
        StreamState stream = streamForWrite(frame.id, txn);
        if (stream.stop == null) {
            setStop(stream, frame.errorCode, txn);
        }
    }

    private void applyCrypto(Frame frame, int level, Txn txn, int offset) throws FrameError {
        if (frame.offset > MAX62 - frame.length) {
            throw new FrameError(FRAME_ENCODING_ERROR, offset);
        }
        if (!crypto[level].store(frame.offset, frame.data, txn.journal)) {
            throw new FrameError(PROTOCOL_VIOLATION, offset);
        }
    }

    private void applyStream(Frame frame, Txn txn, int offset) throws FrameError {
        checkStreamReference(frame.id, true, offset);
        if (frame.offset > MAX62 - frame.length) {
            throw new FrameError(FRAME_ENCODING_ERROR, offset);
        }
        long end = frame.offset + frame.length;
        StreamState stream = streamForWrite(frame.id, txn);
        if (stream.finalSize != null) {
            if (end > stream.finalSize) {
                throw new FrameError(FINAL_SIZE_ERROR, offset);
            }
            if (frame.fin && end != stream.finalSize) {
                throw new FrameError(FINAL_SIZE_ERROR, offset);
            }
        } else if (frame.fin) {
            if (end < stream.high) {
                throw new FrameError(FINAL_SIZE_ERROR, offset);
            }
            setFinalSize(stream, end, txn);
        }
        applyFlowControl(stream, end, txn, offset);
        if (stream.reset == null) {
            if (!stream.data.store(frame.offset, frame.data, txn.journal)) {
                throw new FrameError(PROTOCOL_VIOLATION, offset);
            }
        }
    }

    private void applyFlowControl(StreamState stream, long end, Txn txn, int offset)
            throws FrameError {
        long candidate = Math.max(stream.high, end);
        if (candidate > limitStream) {
            throw new FrameError(FLOW_CONTROL_ERROR, offset);
        }
        long newUsed = used + (candidate - stream.high);
        if (newUsed > limitConnection) {
            throw new FrameError(FLOW_CONTROL_ERROR, offset);
        }
        if (candidate != stream.high) {
            long old = stream.high;
            stream.high = candidate;
            txn.journal.add(() -> stream.high = old);
            long previousUsed = used;
            used = newUsed;
            txn.journal.add(() -> used = previousUsed);
        }
    }

    private void applyMaxData(Frame frame, Txn txn) {
        if (frame.finalSize > sendMaxData) {
            long old = sendMaxData;
            sendMaxData = frame.finalSize;
            txn.journal.add(() -> sendMaxData = old);
        }
    }

    private void applyMaxStreamData(Frame frame, Txn txn, int offset) throws FrameError {
        checkStreamReference(frame.id, false, offset);
        StreamState stream = streamForWrite(frame.id, txn);
        if (frame.finalSize > stream.sendMax) {
            long old = stream.sendMax;
            stream.sendMax = frame.finalSize;
            txn.journal.add(() -> stream.sendMax = old);
        }
    }

    private void applyMaxStreams(Frame frame, Txn txn, int offset) throws FrameError {
        if (frame.finalSize > MAX60) {
            throw new FrameError(FRAME_ENCODING_ERROR, offset);
        }
        boolean bidi = frame.type == 0x12;
        long old = bidi ? sendMaxStreamsBidi : sendMaxStreamsUni;
        if (frame.finalSize > old) {
            if (bidi) {
                sendMaxStreamsBidi = frame.finalSize;
            } else {
                sendMaxStreamsUni = frame.finalSize;
            }
            txn.journal.add(() -> {
                if (bidi) {
                    sendMaxStreamsBidi = old;
                } else {
                    sendMaxStreamsUni = old;
                }
            });
        }
    }

    private void applyStreamsBlocked(Frame frame, int offset) throws FrameError {
        if (frame.finalSize > MAX60) {
            throw new FrameError(FRAME_ENCODING_ERROR, offset);
        }
    }

    private void applyStreamDataBlocked(Frame frame, Txn txn, int offset) throws FrameError {
        checkStreamReference(frame.id, true, offset);
        streamForWrite(frame.id, txn);
    }

    private void applyNewConnectionId(Frame frame, Txn txn, int offset) throws FrameError {
        if (frame.retirePriorTo > frame.sequence) {
            throw new FrameError(FRAME_ENCODING_ERROR, offset);
        }
        if (frame.cidLength < 1 || frame.cidLength > 20) {
            throw new FrameError(FRAME_ENCODING_ERROR, offset);
        }
        PeerCid known = peerCids.get(frame.sequence);
        if (known != null && (!Arrays.equals(known.cid, frame.cid)
                || !Arrays.equals(known.token, frame.token))) {
            throw new FrameError(PROTOCOL_VIOLATION, offset);
        }
        String key = Main.hex(frame.cid);
        Long owner = cidOwner.get(key);
        if (owner != null && owner.longValue() != frame.sequence) {
            throw new FrameError(PROTOCOL_VIOLATION, offset);
        }
        snapshotPeerState(txn);
        peerCids.put(frame.sequence, new PeerCid(frame.cid, frame.token));
        cidOwner.put(key, frame.sequence);
        if (frame.retirePriorTo > retirePriorTo) {
            long old = retirePriorTo;
            retirePriorTo = frame.retirePriorTo;
            txn.journal.add(() -> retirePriorTo = old);
        }
        int active = 0;
        for (Long sequence : peerCids.keySet()) {
            if (sequence >= retirePriorTo) {
                active++;
            }
        }
        if (active > limitCids) {
            throw new FrameError(CONNECTION_ID_LIMIT_ERROR, offset);
        }
    }

    private void snapshotPeerState(Txn txn) {
        if (txn.peerSnapshot) {
            return;
        }
        txn.peerSnapshot = true;
        TreeMap<Long, PeerCid> cids = new TreeMap<>(peerCids);
        Map<String, Long> owner = new HashMap<>(cidOwner);
        long threshold = retirePriorTo;
        txn.journal.add(() -> {
            peerCids.clear();
            peerCids.putAll(cids);
            cidOwner.clear();
            cidOwner.putAll(owner);
            retirePriorTo = threshold;
        });
    }

    private void applyRetireConnectionId(Frame frame, Txn txn, int destination, int offset)
            throws FrameError {
        if (frame.sequence >= localCids.length) {
            throw new FrameError(PROTOCOL_VIOLATION, offset);
        }
        if (frame.sequence == destination) {
            throw new FrameError(PROTOCOL_VIOLATION, offset);
        }
        int index = (int) frame.sequence;
        if (!localRetired[index]) {
            if (!txn.cidSnapshot) {
                txn.cidSnapshot = true;
                boolean[] snapshot = localRetired.clone();
                txn.journal.add(() -> System.arraycopy(snapshot, 0, localRetired, 0, snapshot.length));
            }
            localRetired[index] = true;
        }
    }

    /**
     * Checks direction and stream count of a stream reference.
     *
     * @param receive true for receive direction references
     */
    private void checkStreamReference(long id, boolean receive, int offset) throws FrameError {
        int type = (int) (id & 3);
        long index = id >>> 2;
        switch (type) {
            case 0:
                if (index >= limitBidi) {
                    throw new FrameError(STREAM_LIMIT_ERROR, offset);
                }
                break;
            case 2:
                if (!receive) {
                    throw new FrameError(STREAM_STATE_ERROR, offset);
                }
                if (index >= limitUni) {
                    throw new FrameError(STREAM_LIMIT_ERROR, offset);
                }
                break;
            case 1:
                if (index >= localBidi) {
                    throw new FrameError(STREAM_STATE_ERROR, offset);
                }
                break;
            default:
                if (receive || index >= localUni) {
                    throw new FrameError(STREAM_STATE_ERROR, offset);
                }
                break;
        }
    }

    private StreamState streamForWrite(long id, Txn txn) {
        StreamState stream = streams.get(id);
        if (stream == null) {
            stream = new StreamState();
            streams.put(id, stream);
            txn.journal.add(() -> streams.remove(id));
        }
        return stream;
    }

    private void setFinalSize(StreamState stream, long value, Txn txn) {
        Long old = stream.finalSize;
        stream.finalSize = value;
        txn.journal.add(() -> stream.finalSize = old);
    }

    private void setReset(StreamState stream, long value, Txn txn) {
        Long old = stream.reset;
        stream.reset = value;
        txn.journal.add(() -> stream.reset = old);
    }

    private void setStop(StreamState stream, long value, Txn txn) {
        Long old = stream.stop;
        stream.stop = value;
        txn.journal.add(() -> stream.stop = old);
    }

    // ------------------------------------------------------------------ canonical output

    private static byte[] canonicalPayload(List<Frame> frames) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (Frame frame : frames) {
            byte[] bytes = frame.canonical();
            out.write(bytes, 0, bytes.length);
        }
        return out.toByteArray();
    }

    private byte[] canonicalEnvelope(Envelope envelope, long pn, long expected, byte[] payload) {
        int width = choosePnWidth(pn, expected);
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        if (envelope.level < 2) {
            int first = (envelope.level == 0 ? 0xC0 : 0xE0) | (width - 1);
            out.write(first);
            out.write(0);
            out.write(0);
            out.write(0);
            out.write(1);
            out.write(envelope.dcid.length);
            out.write(envelope.dcid, 0, envelope.dcid.length);
            out.write(envelope.scid.length);
            out.write(envelope.scid, 0, envelope.scid.length);
            if (envelope.level == 0) {
                byte[] token = QuicVarint.encode(envelope.token.length);
                out.write(token, 0, token.length);
                out.write(envelope.token, 0, envelope.token.length);
            }
            byte[] length = QuicVarint.encode(width + (long) payload.length);
            out.write(length, 0, length.length);
            writePacketNumber(out, pn, width);
        } else {
            int first = 0x40 | (envelope.keyPhase << 2) | (width - 1);
            out.write(first);
            out.write(envelope.dcid, 0, envelope.dcid.length);
            writePacketNumber(out, pn, width);
        }
        out.write(payload, 0, payload.length);
        return out.toByteArray();
    }

    private static void writePacketNumber(ByteArrayOutputStream out, long pn, int width) {
        for (int i = width - 1; i >= 0; i--) {
            out.write((int) ((pn >>> (8 * i)) & 0xFF));
        }
    }

    private static int choosePnWidth(long pn, long expected) {
        for (int width = 1; width <= 4; width++) {
            long mask = width == 4 ? 0xFFFFFFFFL : ((1L << (8 * width)) - 1);
            long raw = pn & mask;
            if (reconstruct(raw, width, expected) == pn) {
                return width;
            }
        }
        return 4;
    }

    /** Reconstructs the full packet number from a truncated one. */
    static long reconstruct(long raw, int width, long expected) {
        long modulus = width >= 4 ? (1L << 32) : (1L << (8 * width));
        long best = raw;
        long bestDistance = Math.abs(raw - expected);
        long candidate = raw + modulus;
        long distance = Math.abs(candidate - expected);
        if (distance < bestDistance || (distance == bestDistance && candidate > best)) {
            best = candidate;
            bestDistance = distance;
        }
        if (raw >= modulus) {
            candidate = raw - modulus;
            distance = Math.abs(candidate - expected);
            if (distance < bestDistance || (distance == bestDistance && candidate > best)) {
                best = candidate;
            }
        }
        return best;
    }

    // ------------------------------------------------------------------ result

    private Map<String, Object> buildResult() {
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("packets", packetRows);
        result.put("datagrams", datagramRows);
        if (closedInfo == null) {
            result.put("closed", null);
        } else {
            result.put("closed", Main.object(
                    "event", closedInfo[0],
                    "packet", closedInfo[1],
                    "offset", closedInfo[2],
                    "code", closedCode));
        }
        List<Object> keys = new ArrayList<>();
        for (int level = 0; level < 3; level++) {
            if (keyActive[level]) {
                keys.add(levelName(level));
            }
        }
        result.put("keys", keys);
        result.put("received", Main.object(
                "I", largest[0] < 0 ? null : (Object) Long.valueOf(largest[0]),
                "H", largest[1] < 0 ? null : (Object) Long.valueOf(largest[1]),
                "A", largest[2] < 0 ? null : (Object) Long.valueOf(largest[2])));
        result.put("key_epoch", currentEpoch);
        List<Object> epochRows = new ArrayList<>();
        for (Map.Entry<Long, long[]> entry : epochs.entrySet()) {
            epochRows.add(Main.object(
                    "epoch", entry.getKey(),
                    "min", entry.getValue()[0],
                    "max", entry.getValue()[1],
                    "count", entry.getValue()[2]));
        }
        result.put("epochs", epochRows);
        result.put("opened", Main.object("bidi", openedBidi, "uni", openedUni));
        result.put("used", used);
        result.put("send_max_data", sendMaxData);
        result.put("send_max_streams", Main.object(
                "bidi", sendMaxStreamsBidi, "uni", sendMaxStreamsUni));
        List<Object> streamRows = new ArrayList<>();
        for (Map.Entry<Long, StreamState> entry : streams.entrySet()) {
            StreamState stream = entry.getValue();
            streamRows.add(Main.object(
                    "id", entry.getKey(),
                    "high", stream.high,
                    "final", stream.finalSize,
                    "reset", stream.reset,
                    "stop", stream.stop,
                    "send_max", stream.sendMax,
                    "ranges", rangeList(stream.data.ranges()),
                    "unique", stream.data.unique(),
                    "prefix", stream.data.prefix(),
                    "sha256", prefixHash(stream.data)));
        }
        result.put("streams", streamRows);
        List<Object> cryptoRows = new ArrayList<>();
        for (int level = 0; level < 3; level++) {
            cryptoRows.add(Main.object(
                    "level", levelName(level),
                    "ranges", rangeList(crypto[level].ranges()),
                    "unique", crypto[level].unique(),
                    "prefix", crypto[level].prefix(),
                    "sha256", prefixHash(crypto[level])));
        }
        result.put("crypto", cryptoRows);
        List<Object> ackRows = new ArrayList<>();
        for (int level = 0; level < 3; level++) {
            ackRows.add(Main.object(
                    "level", levelName(level),
                    "count", ackRanges[level].count(),
                    "intervals", ackRanges[level].intervalCount(),
                    "prefix", ackRanges[level].prefix(),
                    "sha256", intervalHash(ackRanges[level]),
                    "ecn", Main.object(
                            "ect0", ecn[level][0],
                            "ect1", ecn[level][1],
                            "ce", ecn[level][2])));
        }
        result.put("acknowledged", ackRows);
        List<Object> peerRows = new ArrayList<>();
        for (Map.Entry<Long, PeerCid> entry : peerCids.entrySet()) {
            if (entry.getKey() < retirePriorTo) {
                continue;
            }
            peerRows.add(Main.object(
                    "sequence", entry.getKey(),
                    "id", Main.hex(entry.getValue().cid),
                    "token", Main.hex(entry.getValue().token)));
        }
        result.put("peer_cids", peerRows);
        result.put("retire_prior_to", retirePriorTo);
        result.put("retired_local", retiredLocalIntervals());
        return result;
    }

    private static List<Object> rangeList(List<long[]> ranges) {
        List<Object> result = new ArrayList<>(ranges.size());
        for (long[] range : ranges) {
            result.add(Arrays.asList(Long.valueOf(range[0]), Long.valueOf(range[1])));
        }
        return result;
    }

    private static String prefixHash(ByteStore store) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            store.digestPrefix(digest);
            return hex(digest.digest());
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private static String intervalHash(IntervalSet intervals) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            for (long[] interval : intervals.list()) {
                digest.update(longBytes(interval[0]));
                digest.update(longBytes(interval[1]));
            }
            return hex(digest.digest());
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private static byte[] longBytes(long value) {
        byte[] out = new byte[8];
        for (int i = 0; i < 8; i++) {
            out[7 - i] = (byte) ((value >>> (8 * i)) & 0xFF);
        }
        return out;
    }

    private static String hex(byte[] data) {
        char[] digits = "0123456789abcdef".toCharArray();
        StringBuilder builder = new StringBuilder(data.length * 2);
        for (byte value : data) {
            builder.append(digits[(value & 0xFF) >>> 4]);
            builder.append(digits[value & 0x0F]);
        }
        return builder.toString();
    }

    private List<Object> retiredLocalIntervals() {
        List<Object> result = new ArrayList<>();
        long start = -1;
        for (int index = 0; index < localRetired.length; index++) {
            if (localRetired[index]) {
                if (start < 0) {
                    start = index;
                }
            } else if (start >= 0) {
                result.add(Arrays.asList(Long.valueOf(start), Long.valueOf(index)));
                start = -1;
            }
        }
        if (start >= 0) {
            result.add(Arrays.asList(Long.valueOf(start), Long.valueOf((long) localRetired.length)));
        }
        return result;
    }
